      ,ID_TAG_TP  = #{recharging.idTagType}
      ,PRD_ID	  = #{recharging.productId}
      ,CH_ST_DT	  = #{recharging.chStartDate}
      ,CH_ED_DT	  = #{recharging.chEndDate}
      ,CH_STAT_CD = #{recharging.chStatCode}
      ,CH_US_AMT  = #{recharging.chUseAmount}
      ,CH_US_CST  = #{recharging.chUseUnitCost}
      ,CH_US_SUM  = #{recharging.chUseCost}
      ,PAY_SUM	  = #{recharging.paySum}
      ,ST_CA_ELE_NRG  = #{recharging.startCaEleEnerge}
      ,ED_CA_ELE_NRG  = #{recharging.endCaEleEnerge}
      ,MAX_ENERGY = #{recharging.maxEnergy}
      ,PK_ST_DT   = #{recharging.pkStartDate}
